18	
19	import io.fabric8.kubernetes.api.model.Service;
20	import io.fabric8.kubernetes.client.KubernetesClient;
21	import io.fabric8.kubernetes.client.ServiceToURLProvider;
22	import io.fabric8.kubernetes.client.utils.internal.URLFromServiceUtil;
23	import org.slf4j.Logger;
24	import org.slf4j.LoggerFactory;
25	
26	public class URLFromEnvVarsImpl implements ServiceToURLProvider {
27	  public static final Logger logger = LoggerFactory.getLogger(URLFromEnvVarsImpl.class);
28	
29	  public static final String ANNOTATION_EXPOSE_URL = "fabric8.io/exposeUrl";
30	
31	  @Override
32	  public String getURL(Service service, String portName, String namespace, KubernetesClient client) {
33	    String serviceHost = URLFromServiceUtil.resolveHostFromEnvVarOrSystemProperty(service.getMetadata().getName());
34	    String servicePort = URLFromServiceUtil.resolvePortFromEnvVarOrSystemProperty(service.getMetadata().getName(), "");
35	    String serviceProtocol = URLFromServiceUtil
36	        .resolveProtocolFromEnvVarOrSystemProperty(service.getSpec().getPorts().iterator().next().getProtocol(), "");
37	
38	    if (!serviceHost.isEmpty() && !servicePort.isEmpty() && !serviceProtocol.isEmpty()) {
39	      return serviceProtocol + "://" + serviceHost + ":" + servicePort;
40	    } else {
41	      String answer = URLFromServiceUtil.getOrCreateAnnotations(service).get(ANNOTATION_EXPOSE_URL);
42	      if (answer != null && !answer.isEmpty()) {
43	        return answer;
44	      }
45	    }
46	    return null;
47	  }
48	
49	  @Override
50	  public int getPriority() {
51	    return ServiceToUrlImplPriority.THIRD.getValue();
52	  }
53	}
