17	package io.fabric8.kubernetes.client.utils.internal;
18	
19	import io.fabric8.kubernetes.api.model.*;
20	import io.fabric8.kubernetes.api.model.extensions.*;
21	import io.fabric8.kubernetes.client.utils.URLUtils;
22	import org.slf4j.Logger;
23	import org.slf4j.LoggerFactory;
24	
25	import java.util.LinkedHashMap;
26	import java.util.List;
27	import java.util.Locale;
28	import java.util.Map;
29	import java.util.Objects;
30	
31	public class URLFromServiceUtil {
32	  public static final Logger logger = LoggerFactory.getLogger(URLFromServiceUtil.class);
33	  public static final String DEFAULT_PROTO = "tcp";
34	  private static final String HOST_SUFFIX = "_SERVICE_HOST";
35	  private static final String PORT_SUFFIX = "_SERVICE_PORT";
36	  private static final String PROTO_SUFFIX = "_TCP_PROTO";
37	
38	  private URLFromServiceUtil() {
39	    throw new IllegalStateException("Utility class");
40	  }
41	
42	  public static String resolveHostFromEnvVarOrSystemProperty(String serviceName) {
43	    return getEnvVarOrSystemProperty(toServiceHostEnvironmentVariable(serviceName), "");
44	  }
45	
46	  private static String getEnvVarOrSystemProperty(String envVarName, String defaultValue) {
47	    String answer = null;
48	    try {
49	      answer = System.getenv(envVarName);
50	    } catch (Exception e) {
51	      logger.warn("Failed to look up environment variable $" + envVarName + ". " + e, e);
52	    }
53	    if (answer == null || answer.isEmpty()) {
54	      answer = System.getProperty(envVarName, defaultValue);
55	    }
56	    if (!answer.isEmpty()) {
57	      return answer;
58	    } else {
59	      return defaultValue;
60	    }
61	  }
62	
63	  public static String resolveProtocolFromEnvVarOrSystemProperty(String serviceName, String servicePort) {
64	    return getEnvVarOrSystemProperty(toEnvVariable(serviceName + PORT_SUFFIX + "_" + servicePort + PROTO_SUFFIX),
65	        DEFAULT_PROTO);
66	  }
67	
68	  public static Map<String, String> getOrCreateAnnotations(HasMetadata entity) {
69	    ObjectMeta metadata = getOrCreateMetadata(entity);
70	    Map<String, String> answer = metadata.getAnnotations();
71	    if (answer == null) {
72	      // use linked so the annotations can be in the FIFO order
73	      answer = new LinkedHashMap<>();
74	      metadata.setAnnotations(answer);
75	    }
76	    return answer;
77	  }
78	
79	  public static ObjectMeta getOrCreateMetadata(HasMetadata entity) {
80	    ObjectMeta metadata = entity.getMetadata();
81	    if (metadata == null) {
82	      metadata = new ObjectMeta();
83	      entity.setMetadata(metadata);
84	    }
85	    return metadata;
86	  }
87	
88	  public static String resolvePortFromEnvVarOrSystemProperty(String serviceName, String portName) {
89	    String envVarName = toServicePortEnvironmentVariable(serviceName, portName);
90	    return getEnvVarOrSystemProperty(envVarName, "");
91	  }
92	
93	  public static String toServicePortEnvironmentVariable(String serviceName, String portName) {
94	    String name = serviceName + PORT_SUFFIX + (portName.isEmpty() ? "_" + portName : "");
95	    return toEnvVariable(name);
96	  }
97	
98	  private static String toServiceHostEnvironmentVariable(String serviceName) {
99	    return toEnvVariable(serviceName + HOST_SUFFIX);
100	  }
101	
102	  public static String toEnvVariable(String serviceName) {
103	    return serviceName.toUpperCase(Locale.ROOT).replaceAll("-", "_");
104	  }
105	
106	  public static String getURLFromIngressList(List<Ingress> ingressList, String namespace, String serviceName,
107	      ServicePort port) {
108	    for (Ingress item : ingressList) {
109	      String ns = getNamespace(item);
110	      if (Objects.equals(ns, namespace) && item.getSpec() != null) {
111	        return getURLFromIngressSpec(item.getSpec(), serviceName, port);
112	      }
113	    }
114	    return null;
115	  }
116	
117	  public static String getURLFromIngressSpec(IngressSpec spec, String serviceName, ServicePort port) {
118	    List<IngressRule> ingressRules = spec.getRules();
119	    if (ingressRules != null && !ingressRules.isEmpty()) {
120	      for (IngressRule rule : ingressRules) {
121	        HTTPIngressRuleValue http = rule.getHttp();
122	        if (http != null && http.getPaths() != null) {
123	          return getURLFromIngressRules(http.getPaths(), spec, serviceName, port, rule);
124	        }
125	      }
126	    }
127	    return null;
128	  }
129	
130	  public static String getURLFromIngressRules(List<HTTPIngressPath> paths, IngressSpec spec, String serviceName,
131	      ServicePort port, IngressRule rule) {
132	    for (HTTPIngressPath path : paths) {
133	      IngressBackend backend = path.getBackend();
134	      if (backend != null) {
135	        String backendServiceName = backend.getServiceName();
136	        if (serviceName.equals(backendServiceName) && portsMatch(port, backend.getServicePort())) {
137	          String pathPostFix = path.getPath();
138	          if (spec.getTls() != null) {
139	            return getURLFromTLSHost(rule, pathPostFix);
140	          }
141	          String answer = rule.getHost();
142	          if (answer != null && !answer.isEmpty()) {
143	            pathPostFix = fixPathPostFixIfEmpty(pathPostFix);
144	            return "http://" + URLUtils.pathJoin(answer, pathPostFix);
145	          }
146	        }
147	      }
148	    }
149	    return null;
150	  }
151	
152	  public static String getURLFromTLSHost(IngressRule rule, String pathPostFix) {
153	    String host = rule.getHost();
154	    if (!host.isEmpty()) {
155	      pathPostFix = fixPathPostFixIfEmpty(pathPostFix);
156	      return "https://" + URLUtils.pathJoin(host, pathPostFix);
157	    }
158	    return null;
159	  }
160	
161	  private static String fixPathPostFixIfEmpty(String pathPostFix) {
162	    return pathPostFix.isEmpty() ? "/" : pathPostFix;
163	  }
164	
165	  private static boolean portsMatch(ServicePort servicePort, IntOrString intOrString) {
166	    if (intOrString != null) {
167	      Integer port = servicePort.getPort();
168	      Integer intVal = intOrString.getIntVal();
169	      String strVal = intOrString.getStrVal();
170	      if (intVal != null) {
171	        if (port != null) {
172	          return port.intValue() == intVal.intValue();
173	        } else {
174	          /// should we find the port by name now?
175	        }
176	      } else if (strVal != null) {
177	        return strVal.equals(servicePort.getName());
178	      }
179	    }
180	    return false;
181	  }
182	
183	  public static String getNamespace(HasMetadata entity) {
184	    if (entity != null) {
185	      return entity.getMetadata() != null ? entity.getMetadata().getNamespace() : null;
186	    } else {
187	      return null;
188	    }
189	  }
190	
191	  public static ServicePort getServicePortByName(Service service, String portName) {
192	    if (portName.isEmpty()) {
193	      return service.getSpec().getPorts().iterator().next();
194	    }
195	
196	    for (ServicePort servicePort : service.getSpec().getPorts()) {
197	      if (Objects.equals(servicePort.getName(), portName)) {
198	        return servicePort;
199	      }
200	    }
201	    return null;
202	  }
203	}
